/**
 * Pathixo Rewards — Referral Engine & Economic Safeguards
 * 
 * Rules:
 * 1. 10% Weekly Royalty: Referrer gets 10% of verified earnings generated by their referrals.
 * 2. Capped at $10.00 Max per Referral: Royalty continues until cumulative commission from that referred user reaches $10.00.
 * 3. Weekly Turnaround: Calculated and disbursed at the end of each weekly cycle based on weekly verified earnings.
 * 4. Economic Safeguard: Funded entirely out of Pathixo's 40% platform take; referred user always receives their full 60%.
 *    (Adjusted revenue split during active royalty: Referrer: 4%, User: 60%, Platform: 36%).
 * 5. Welcome Milestone Credit: Referred user unlocks an instant $0.25 bonus after their first 10 verified impressions.
 */

export interface ReferralRelationship {
  id: string;
  referrer_device_id: string;
  referred_device_id: string;
  created_at: string;
  total_commission_usd: number; // Max $10.00 cap
  is_active: boolean; // false once total_commission_usd >= 10.0
  welcome_credit_unlocked: boolean;
  welcome_credit_impressions: number; // tracks progress toward 10 impressions
  current_week_earnings_usd: number;
}

export interface WeeklyTurnaroundSummary {
  week_ending: string;
  processed_referrals: number;
  total_disbursed_usd: number;
  capped_referrals_count: number;
}

export const REFERRAL_COMMISSION_PERCENT = 0.10; // 10%
export const REFERRAL_MAX_CAP_USD = 10.00; // $10 cap per referred user
export const WELCOME_CREDIT_USD = 0.25; // $0.25 instant milestone credit
export const WELCOME_CREDIT_IMPRESSIONS_REQUIRED = 10; // 10 verified impressions

class ReferralEngine {
  private relationships = new Map<string, ReferralRelationship>(); // key: referred_device_id

  /**
   * Register a new referral connection when a new user signs up or installs via ?ref=referrer_id
   */
  public registerReferral(referrerDeviceId: string, referredDeviceId: string): ReferralRelationship | null {
    if (!referrerDeviceId || !referredDeviceId || referrerDeviceId === referredDeviceId) {
      return null;
    }

    if (this.relationships.has(referredDeviceId)) {
      return this.relationships.get(referredDeviceId)!;
    }

    const rel: ReferralRelationship = {
      id: `ref_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
      referrer_device_id: referrerDeviceId,
      referred_device_id: referredDeviceId,
      created_at: new Date().toISOString(),
      total_commission_usd: 0,
      is_active: true,
      welcome_credit_unlocked: false,
      welcome_credit_impressions: 0,
      current_week_earnings_usd: 0,
    };

    this.relationships.set(referredDeviceId, rel);
    return rel;
  }

  /**
   * Track a verified impression from a user to record earnings and check welcome milestone
   */
  public recordVerifiedImpression(deviceId: string, earnedAmountUsd: number): {
    welcomeMilestoneUnlocked: boolean;
    welcomeCreditAmount: number;
  } {
    const rel = this.relationships.get(deviceId);
    if (!rel) {
      return { welcomeMilestoneUnlocked: false, welcomeCreditAmount: 0 };
    }

    // Accumulate current week earnings if referral is still under $10 cap
    if (rel.is_active) {
      rel.current_week_earnings_usd += earnedAmountUsd;
    }

    // Check Welcome Milestone Credit (Unlocked after 10 verified impressions)
    rel.welcome_credit_impressions += 1;
    let unlocked = false;
    let credit = 0;

    if (!rel.welcome_credit_unlocked && rel.welcome_credit_impressions >= WELCOME_CREDIT_IMPRESSIONS_REQUIRED) {
      rel.welcome_credit_unlocked = true;
      unlocked = true;
      credit = WELCOME_CREDIT_USD;
    }

    return {
      welcomeMilestoneUnlocked: unlocked,
      welcomeCreditAmount: credit,
    };
  }

  /**
   * Execute weekly turnaround settlement:
   * Calculates 10% of each referred user's weekly earnings and credits to referrer,
   * enforcing the $10.00 lifetime cap per referee.
   */
  public processWeeklyTurnaround(): WeeklyTurnaroundSummary {
    let totalDisbursed = 0;
    let processedCount = 0;
    let cappedCount = 0;

    for (const rel of this.relationships.values()) {
      if (!rel.is_active || rel.current_week_earnings_usd <= 0) {
        // Reset week earnings even if inactive
        rel.current_week_earnings_usd = 0;
        continue;
      }

      processedCount++;
      const rawCommission = Number((rel.current_week_earnings_usd * REFERRAL_COMMISSION_PERCENT).toFixed(4));
      const remainingAllowance = Math.max(0, REFERRAL_MAX_CAP_USD - rel.total_commission_usd);
      const payableCommission = Math.min(rawCommission, remainingAllowance);

      if (payableCommission > 0) {
        rel.total_commission_usd = Number((rel.total_commission_usd + payableCommission).toFixed(4));
        totalDisbursed = Number((totalDisbursed + payableCommission).toFixed(4));
      }

      if (rel.total_commission_usd >= REFERRAL_MAX_CAP_USD) {
        rel.is_active = false;
        cappedCount++;
      }

      // Reset for next weekly turnaround cycle
      rel.current_week_earnings_usd = 0;
    }

    return {
      week_ending: new Date().toISOString(),
      processed_referrals: processedCount,
      total_disbursed_usd: totalDisbursed,
      capped_referrals_count: cappedCount,
    };
  }

  /**
   * Retrieve referral statistics for a specific referrer
   */
  public getReferrerStats(referrerDeviceId: string): {
    totalReferrals: number;
    activeReferrals: number;
    cappedReferrals: number;
    totalEarnedUsd: number;
    pendingWeeklyTurnaroundUsd: number;
    maxCapPerReferral: number;
  } {
    let total = 0;
    let active = 0;
    let capped = 0;
    let totalEarned = 0;
    let pendingWeekly = 0;

    for (const rel of this.relationships.values()) {
      if (rel.referrer_device_id === referrerDeviceId) {
        total++;
        if (rel.is_active) {
          active++;
          pendingWeekly += Number((rel.current_week_earnings_usd * REFERRAL_COMMISSION_PERCENT).toFixed(4));
        } else {
          capped++;
        }
        totalEarned += rel.total_commission_usd;
      }
    }

    return {
      totalReferrals: total,
      activeReferrals: active,
      cappedReferrals: capped,
      totalEarnedUsd: Number(totalEarned.toFixed(4)),
      pendingWeeklyTurnaroundUsd: Number(pendingWeekly.toFixed(4)),
      maxCapPerReferral: REFERRAL_MAX_CAP_USD,
    };
  }

  /**
   * Retrieve referee onboarding status
   */
  public getRefereeStatus(referredDeviceId: string): ReferralRelationship | null {
    return this.relationships.get(referredDeviceId) || null;
  }

  /**
   * Clear all records (useful for test isolation)
   */
  public reset(): void {
    this.relationships.clear();
  }
}

// Global Singleton
export const referralEngine = new ReferralEngine();
